import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, spring } from "remotion";
import { COLORS, FONTS, headlineGradient, ENGRAVE_SHADOW } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

type Node = { title: string; sub: string };

const Connector: React.FC<{ S: number; grow: number; dot: number }> = ({ S, grow, dot }) => (
  <div style={{ position: "relative", height: 104 * S, width: 8 * S, display: "flex", justifyContent: "center" }}>
    <div style={{ position: "absolute", top: 0, left: 0, width: "100%", height: `${Math.max(0, Math.min(1, grow)) * 100}%`, background: COLORS.gold, borderRadius: 999, opacity: 0.9 }} />
    <div
      style={{
        position: "absolute",
        bottom: -2 * S,
        left: "50%",
        transform: `translateX(-50%) scale(${grow > 0.92 ? 1 : 0})`,
        width: 0,
        height: 0,
        borderLeft: `${13 * S}px solid transparent`,
        borderRight: `${13 * S}px solid transparent`,
        borderTop: `${18 * S}px solid ${COLORS.gold}`,
      }}
    />
    {dot >= 0 && dot <= 1 ? (
      <div
        style={{
          position: "absolute",
          top: `${dot * 100}%`,
          left: "50%",
          transform: "translate(-50%,-50%)",
          width: 16 * S,
          height: 16 * S,
          borderRadius: 999,
          background: COLORS.tealBright,
          boxShadow: `0 0 ${22 * S}px ${COLORS.tealBright}`,
        }}
      />
    ) : null}
  </div>
);

const SourceFlow: React.FC<PrimitiveProps> = ({ anim, fps, dark, frame }) => {
  const f = useCurrentFrame();
  const S = Math.min(frame.width / 1080, frame.height / 1920);
  const txt = dark ? COLORS.textOnDark : COLORS.textOnLight;
  const muted = dark ? COLORS.mutedOnDark : COLORS.mutedOnLight;

  const rawNodes = Array.isArray(anim.params?.nodes) ? (anim.params?.nodes as unknown[]) : [];
  const nodes: Node[] = (rawNodes.length ? rawNodes : []).map((n) => {
    const o = (n ?? {}) as Record<string, unknown>;
    return { title: String(o.title ?? ""), sub: String(o.sub ?? "") };
  });
  const list: Node[] = nodes.length
    ? nodes
    : [
        { title: "PEXELS", sub: "videos — published without audio" },
        { title: "PIXABAY", sub: "free music & sound effects" },
        { title: "YOUR VIDEO", sub: "sound on" },
      ];
  const note = String(anim.params?.note ?? "");

  const nodeStart = (i: number) => 4 + i * 28;
  const armStart = (i: number) => 18 + i * 28;

  const noteIn = spring({ frame: f - (nodeStart(list.length - 1) + 18), fps, config: { damping: 200, mass: 0.7 } });

  return (
    <AbsoluteFill style={{ fontFamily: FONTS.body, alignItems: "center", justifyContent: "center" }}>
      <div style={{ width: "84%", display: "flex", flexDirection: "column", alignItems: "center" }}>
        {list.map((n, i) => {
          const inn = spring({ frame: f - nodeStart(i), fps, config: { damping: 200, mass: 0.7 } });
          const last = i === list.length - 1;
          const g = interpolate(f, [armStart(i), armStart(i) + 12], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
          const dotPhase = ((f - (armStart(i) + 6)) % 34) / 34;
          const dot = f > armStart(i) + 6 && dotPhase >= 0 ? dotPhase : -1;
          const titleSize = (n.title.length > 12 ? 56 : n.title.length > 8 ? 68 : 78) * S;
          return (
            <React.Fragment key={i}>
              <div
                style={{
                  width: "100%",
                  padding: `${30 * S}px ${34 * S}px`,
                  background: COLORS.vellum,
                  borderRadius: 22 * S,
                  border: `${Math.max(1, 1.4 * S)}px solid rgba(255,255,255,0.12)`,
                  boxShadow: last ? `0 0 ${50 * S}px ${COLORS.teal}33, 0 20px 50px rgba(0,0,0,0.42)` : "0 20px 50px rgba(0,0,0,0.4)",
                  opacity: inn,
                  transform: `translateY(${(1 - inn) * 32 * S}px) scale(${0.95 + 0.05 * inn})`,
                  textAlign: "center",
                }}
              >
                <div
                  style={{
                    fontFamily: FONTS.display,
                    fontWeight: FONTS.displayWeight,
                    textTransform: "uppercase",
                    fontSize: titleSize,
                    lineHeight: 1,
                    backgroundImage: headlineGradient(),
                    WebkitBackgroundClip: "text",
                    backgroundClip: "text",
                    color: "transparent",
                  }}
                >
                  {n.title}
                </div>
                {n.sub ? (
                  <div
                    style={{
                      marginTop: 12 * S,
                      color: muted,
                      fontFamily: FONTS.body,
                      fontWeight: FONTS.bodyWeight,
                      fontSize: 26 * S,
                      lineHeight: 1.35,
                    }}
                  >
                    {n.sub}
                  </div>
                ) : null}
              </div>
              {!last ? <Connector S={S} grow={g} dot={dot} /> : null}
            </React.Fragment>
          );
        })}

        {note ? (
          <div
            style={{
              marginTop: 40 * S,
              color: txt,
              fontFamily: FONTS.mono,
              fontSize: 22 * S,
              letterSpacing: 0.1 * 22 * S,
              textAlign: "center",
              lineHeight: 1.45,
              opacity: noteIn * 0.9,
              transform: `translateY(${(1 - noteIn) * 18 * S}px)`,
              textShadow: ENGRAVE_SHADOW,
            }}
          >
            {note}
          </div>
        ) : null}
      </div>
    </AbsoluteFill>
  );
};

export default SourceFlow;
